Here is a straightforward implementation. It checks the Pythagorean condition for all permutations and also validates that the inputs can form a triangle.

Option 1: using sorted sides (simplest)
def right_angle_triangle(a, b, c):
    # sort the sides so that x <= y <= z
    sides = sorted([a, b, c])
    x, y, z = sides
    # triangle inequality check
    if x <= 0 or x + y <= z:
        return False
    return x*x + y*y == z*z

Option 2: explicit permutation checks (works too)
def right_angle_triangle(a, b, c):
    sides = (a, b, c)
    # triangle inequality
    if any(s <= 0 for s in sides):
        return False
    if not (a + b > c and a + c > b and b + c > a):
        return False
    return (a*a + b*b == c*c) or (a*a + c*c == b*b) or (b*b + c*c == a*a)

