def modular_pow(base, exponent, modulus):
    """Efficiently computes (base^exponent) % modulus using binary exponentiation."""
    if modulus == 1:
        return 0
    result = 1
    base = base % modulus
    while exponent > 0:
        if exponent % 2 == 1:
