    """
    Tests if n is prime using the Miller-Rabin primality test.
    k is the number of rounds, increasing k increases accuracy.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0:
        return False

    # Write n-1 as 2^r * d
    r, d = 0, n - 1
    while d % 2 == 0:
