def _chunk(s, size=3):
    """Yield consecutive chunks of *size* from *s*."""
    for i in range(0, len(s), size):
        yield s[i:i+size]

def encode(s: str) -> str:
    """Split *s* into 3‑character chunks.
    For each full chunk, move the first character to the end.
    Leave incomplete chunks unchanged, then join all chunks."""
    return ''.join(
        chunk[1:] + chunk[0] if len(chunk) == 3 else chunk
        for chunk in _chunk(s)
    )

def decode(s: str) -> str:
    """Inverse of :func:`encode`."""
    return ''.join(
        chunk[-1] + chunk[:-1] if len(chunk) == 3 else chunk
        for chunk in _chunk(s)
    )
