def collatz_sequence(n):
    """
    Generate the Collatz sequence starting from n.
    The sequence ends when it reaches 1.
    """
    sequence = []
    while n != 1:
        sequence.append(n)
        if n % 2 == 0:
            n = n // 2
        else:
            n = 3 * n + 1
    sequence.append(1)
    return sequence

def get_odds_sorted(n):
    """
    Generate the Collatz sequence for n and return the odd numbers sorted.
    """
    sequence = collatz_sequence(n)
    odds = [x for x in sequence if x % 2 != 0]
    return sorted(odds)

