def process_numbers(arr):
    """
    Sorts an array of integers in descending order, converts numbers 
    between 1 and 9 into their English word representation, and filters 
    out numbers outside this range.
    """
    # Define mapping for numbers 1-9
    word_map = {
        1: "One", 2: "Two", 3: "Three", 4: "Four", 5: "Five",
        6: "Six", 7: "Seven", 8: "Eight", 9: "Nine"
    }

    # Functional pipeline: filter range, sort descending, map to words
    return list(
        map(
            lambda x: word_map[x],
            sorted(
                filter(lambda x: 1 <= x <= 9, arr),
                reverse=True
            )
        )
    )
